struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001;
    float2 uv = i.uv - 0.5;
    float aspect = resolution_x / max(1.0, resolution_y);
    uv.x *= aspect;
    float waves = 0.0;
    for (int k = 0; k < 5; k++) {
        float2 center = float2(sin(t * (0.3 + k * 0.17)), cos(t * (0.2 + k * 0.13))) * 0.3;
        float d = length(uv - center);
        waves += sin(d * 30.0 - t * 4.0) / (1.0 + d * 10.0);
    }
    waves *= 0.25;
    float3 deep = float3(0.0, 0.05, 0.2);
    float3 surface = float3(0.1, 0.4, 0.7);
    float3 highlight = float3(0.7, 0.9, 1.0);
    float3 col = lerp(deep, surface, 0.5 + 0.5 * waves);
    col = lerp(col, highlight, saturate(waves * 2.0 - 0.5));
    return float4(col, 1.0);
}
